{"packet_id":"D041-01","doc_id":"D041","jurisdiction":"Los Angeles, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"Los Angeles RSO allowable rent increase","requirement":"Rent may be increased only once every 12 months at the LAHD allowable percentage; utility and dependent add-ons ended February 2, 2026. Increases were prohibited March 30, 2020 through January 31, 2024. Capital improvement, seismic retrofit, rehabilitation and just-and-reasonable increases need LAHD approval.","key_value":"once every 12 months at the allowable rent increase percentage","coverage_conditions":"Rental properties in the City of Los Angeles first built on or before October 1, 1978, plus replacement units under LAMC Section 151.28; apartments, condominiums, townhomes, duplexes, ADUs, hotel rooms, mobile homes and more.","applicability":{"conditions":[{"type":"built","role":"covered","op":"on_or_before","date":"1978-10-01","basis":"construction"},{"type":"other","role":"exempt","text":"Luxury exemption on landlord application where monthly rent on or before May 31, 1978 met the threshold"}],"per_tenancy":"Rent amount not regulated for condominium or townhome tenancies that commenced after December 31, 1995.","coverage_quotes":["Generally, the RSO applies to rental properties that were first built on or before October 1, 1978, as well as replacement units under LAMC Section 151.28 and if any of the following:","Rent amount is not regulated for tenancies that commenced after December 31, 1995","A landlord can apply for an exemption from the RSO if they can establish the monthly rent charged on or before May 31, 1978"]},"exemptions":"Luxury units exempt on landlord application where rent charged on or before May 31, 1978 met the threshold; rent amount not regulated for condominium and townhome tenancies commencing after December 31, 1995.","penalty":null,"effective_date":null,"valid_through":null,"citation":"Los Angeles Rent Stabilization Ordinance (L.A.M.C. §151.00 et seq.)","quoted_span":"Rent may be increased once every 12 months by the allowable rent increase percentage","interaction":null,"relations":[],"confidence":0.75,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D041-01","doc_id":"D041","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Los Angeles RSO legal reasons for eviction","requirement":"Under the RSO a landlord may end a tenancy only for listed at-fault or no-fault reasons. No-fault evictions require relocation assistance, a landlord declaration filed with LAHD, and 30-day and 60-day written notice (longer in some cases).","key_value":"3 business days to file eviction notices; relocation assistance for no-fault evictions","coverage_conditions":"All rental units subject to the City of Los Angeles Rent Stabilization Ordinance (RSO).","applicability":{"conditions":[{"type":"built","role":"covered","op":"on_or_before","date":"1978-10-01","basis":"construction"}],"per_tenancy":null,"coverage_quotes":["All notices to terminate a tenancy for all rental units subject to City’s Rent Stabilization Ordinance (RSO ) must be filed with the Los Angeles Housing Department (LAHD) within three (3) business days of service on the tenant"]},"exemptions":null,"penalty":null,"effective_date":null,"valid_through":null,"citation":"L.A.M.C. § 151.09","quoted_span":"All notices to terminate a tenancy for all rental units subject to City’s Rent Stabilization Ordinance (RSO ) must be filed with the Los Angeles Housing Department (LAHD) within three (3) business days of service on the tenant","interaction":null,"relations":[],"confidence":0.75,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D041-01","n_rules":2,"note":null}

